import * as types from "../types/types";
import pkg from "../../package.json";
import log from "./logger";

export function getDefaultHeaderComment(version?:string): string {
    return `/**
 * Generated by veryExpress@${version} 
 * https://github.com/Justin26l/VeryExpress
 */
`;
}

export function getStaticHeaderComment(): string {
    return `/**
 * Generated by veryExpress 
 * https://github.com/Justin26l/VeryExpress
 */
`;
}

export function getSimpleHeaderComment(): string {
    return `// Generated by veryExpress@${pkg.version}`;
}

export function getSimpleStaticHeaderComment(): string {
    return "// Generated by veryExpress";
}

export function OAuthProviders(compilerOptions: types.compilerOptions): string[] {
    return Object.keys(compilerOptions.auth.oauthProviders!).filter((key) => {
        return compilerOptions.auth.oauthProviders![key] === true;
    });
}

export function isAuthEnabled(compilerOptions: types.compilerOptions): boolean {
    return compilerOptions.auth.localAuth
        || OAuthProviders(compilerOptions).length > 0
        || compilerOptions.auth.firebase === true;
}

/** Auth paths that attach `Authentication.middleware` to generated controllers. */
export function isJwtAuthEnabled(compilerOptions: types.compilerOptions): boolean {
    return compilerOptions.auth.localAuth
        || OAuthProviders(compilerOptions).length > 0;
}

export function isFirebaseAuthEnabled(compilerOptions: types.compilerOptions): boolean {
    return isAuthEnabled(compilerOptions) && compilerOptions.auth.firebase === true;
}

/**
 * Verify-only: tokens are minted elsewhere and this app only checks them.
 *
 * `isAuthEnabled` stays the sign-in question ("can this app log someone in"); it is what gates the
 * login stack and the account tables. Verification is a separate concern, and a project can have
 * exactly one of them.
 */
export function isVerifyOnlyAuthEnabled(compilerOptions: types.compilerOptions): boolean {
    return compilerOptions.auth?.verifyOnly === true;
}

/** Any auth configuration, sign-in or verify-only — the files that read a token at all. */
export function isAuthenticationEnabled(compilerOptions: types.compilerOptions): boolean {
    return isAuthEnabled(compilerOptions) || isVerifyOnlyAuthEnabled(compilerOptions);
}

/** Requests carry a bearer token this app verifies — what the CRUD controllers guard on. */
export function isTokenVerificationEnabled(compilerOptions: types.compilerOptions): boolean {
    return isJwtAuthEnabled(compilerOptions) || isVerifyOnlyAuthEnabled(compilerOptions);
}

export function isAccountDeletionEnabled(compilerOptions: types.compilerOptions): boolean {
    const setting = compilerOptions.auth.deleteAccount;
    const enabled = typeof setting === "object" ? (setting.enabled ?? true) : (setting ?? true);
    return isAuthEnabled(compilerOptions) && enabled;
}

export function deleteAccountTables(compilerOptions: types.compilerOptions): string[] {
    const setting = compilerOptions.auth.deleteAccount;
    return typeof setting === "object" && Array.isArray(setting.deleteTables)
        ? setting.deleteTables
        : [];
}

export function isShowSoftDeleted(compilerOptions: types.compilerOptions): boolean {
    const enabled = compilerOptions.app?.showSoftDeleted ?? false;

    if (enabled) {
        log.warn(
            `app.showSoftDeleted is ON — soft-deleted rows are visible to every query, are writable ` +
            `again through the ordinary CRUD path, and the account-state guard in ` +
            `Authentication.middleware will keep rejecting tombstones. ` +
            `Unset app.showSoftDeleted to restore the default (hidden).`
        );
    }

    return enabled;
}

export function isRbacEnabled(compilerOptions: types.compilerOptions): boolean {
    const roles = compilerOptions.useRBAC?.roles;
    return Array.isArray(roles) && roles.length > 0;
}

export const TENANT_HEADER = "x-tenant-id";
export const TENANT_CLAIM = "tenantId";

export function isTenantEnabled(compilerOptions: types.compilerOptions): boolean {
    return compilerOptions.tenant?.enable === true;
}

export function tenantIsolationMode(compilerOptions: types.compilerOptions): types.TenantIsolationMode {
    return compilerOptions.tenant?.IsolationMode ?? "preSelect";
}

/**
 * Whether the tenant module links accounts to tenants.
 *
 * Membership needs a request identity: `UserTenant`, `TenantService` and every membership check
 * resolve the caller from the access token. `preSelect` without an auth method runs on the
 * `x-tenant-id` header alone, so it owns no mapping table and emits none of those files.
 */
export function isTenantMembershipEnabled(compilerOptions: types.compilerOptions): boolean {
    return isTenantEnabled(compilerOptions) && isAuthEnabled(compilerOptions);
}

export const defaultCompilerOptions: types.compilerOptions = {
    rootDir: ".",
    srcDir: "./src",
    sysDir: "./src/system",
    jsonSchemaDir: "./jsonSchema",
    openapiDir: "./openapi",
    generator: {
        commitBeforeGenerate: false,
    },
    app: {
        enableSwagger: true,
        useUserSchema: true,
        useStatefulRedisAuth: false,
        allowApiCreateUpdate_id: false,
        showSoftDeleted: false,
    },
    useRBAC: {
        roles: ["user"],
        default: "user",
    },
    auth: {
        localAuth: true,
        useHttpOnlyCookieToken: false,
        deleteAccount: true,
        firebase: false,
        verifyOnly: false,
        oauthProviders: {
            google: false,
            microsoft: false,
            apple: false,
            github: false,
        },
    },
    _:{
        writtedDir: [],
    },
    dbType: "sql",
};

export default {
    defaultCompilerOptions,
    getDefaultHeaderComment,
    getStaticHeaderComment,
    getSimpleHeaderComment,
    getSimpleStaticHeaderComment,
    OAuthProviders,
    isAuthEnabled,
    isJwtAuthEnabled,
    isVerifyOnlyAuthEnabled,
    isAuthenticationEnabled,
    isTokenVerificationEnabled,
    isFirebaseAuthEnabled,
    isRbacEnabled,
    isAccountDeletionEnabled,
    isShowSoftDeleted,
    isTenantEnabled,
    isTenantMembershipEnabled,
    tenantIsolationMode,
    TENANT_HEADER,
    TENANT_CLAIM,
    deleteAccountTables,
};